<?php require __DIR__.'/bootstrap.php';if(user())redirect('dashboard.php');$error='';$flashes=$_SESSION['flash']??[];unset($_SESSION['flash']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT u.*,b.name branch_name FROM users u JOIN branches b ON b.id=u.branch_id WHERE u.email=? AND u.active=1 AND b.active=1');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role'],'branch_id'=>(int)$u['branch_id'],'branch_name'=>$u['branch_name'],'permissions'=>$u['permissions']??''];$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$u['id']]);redirect('dashboard.php');}$error='Invalid email or password.';}?>
